import { boolean, index, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core"

/*
 * Tables owned by better-auth (BE-01.3): users, sessions, credentials, verification tokens and the
 * organization plugin (organization = accounting office). They are not tenant-scoped, so they have
 * no row-level security: the API reaches them only through better-auth and the session bridge in
 * src/auth. Each is listed, with the reason, in NON_TENANT_TABLES (tests/integration).
 *
 * Object keys are better-auth's field names; ids are UUIDs generated by Postgres
 * (`advanced.database.generateId: "uuid"`), so an organization id can be the office id.
 */

const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow()
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow()

export const authUsers = pgTable("auth_users", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: text("name").notNull(),
  /** Stored lower-case by better-auth. */
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
})

export const authSessions = pgTable(
  "auth_sessions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    token: text("token").notNull().unique(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: uuid("user_id")
      .notNull()
      .references(() => authUsers.id, { onDelete: "cascade" }),
    /** Active office; the tenant bridge re-checks the membership on every request. */
    activeOrganizationId: uuid("active_organization_id"),
  },
  (t) => [index("auth_sessions_user_id_idx").on(t.userId)],
)

export const authAccounts = pgTable(
  "auth_accounts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: uuid("user_id")
      .notNull()
      .references(() => authUsers.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
    scope: text("scope"),
    /** scrypt hash of the e-mail + password credential. */
    password: text("password"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("auth_accounts_user_id_idx").on(t.userId)],
)

export const authVerifications = pgTable(
  "auth_verifications",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("auth_verifications_identifier_idx").on(t.identifier)],
)

/** better-auth organization; a trigger keeps the matching `offices` row (same id) in sync. */
export const authOrganizations = pgTable("auth_organizations", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  logo: text("logo"),
  metadata: text("metadata"),
  createdAt: createdAt(),
})

export const authMembers = pgTable(
  "auth_members",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => authOrganizations.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => authUsers.id, { onDelete: "cascade" }),
    /** `owner` or `accountant` (src/auth/roles.ts). */
    role: text("role").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index("auth_members_organization_id_idx").on(t.organizationId),
    index("auth_members_user_id_idx").on(t.userId),
  ],
)

export const authInvitations = pgTable(
  "auth_invitations",
  {
    /** Also the secret of the invitation link: a random UUID, valid once and until `expires_at`. */
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => authOrganizations.id, { onDelete: "cascade" }),
    email: text("email").notNull(),
    role: text("role"),
    status: text("status").notNull().default("pending"),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    inviterId: uuid("inviter_id")
      .notNull()
      .references(() => authUsers.id, { onDelete: "cascade" }),
  },
  (t) => [
    index("auth_invitations_organization_id_idx").on(t.organizationId),
    index("auth_invitations_email_idx").on(t.email),
  ],
)

/** Keyed by better-auth model name, as the Drizzle adapter expects. */
export const authSchema = {
  user: authUsers,
  session: authSessions,
  account: authAccounts,
  verification: authVerifications,
  organization: authOrganizations,
  member: authMembers,
  invitation: authInvitations,
}
